forall x R:
    x = x
exist x R st {x = 2}
exist! x R st {x = 3}
not exist x {0} st {x = 1}
not forall x {0, 1}:
    x = 0

witness exist x R st {x = 5} from 5
obtain obtained_a from exist x R st {x = 5}
obtained_a = 5

witness exist! x R st {x = 6} from 6
obtain obtained_b from exist! x R st {x = 6}
obtained_b = 6

witness exist x, y R st {x = 2, y = 3} from 2, 3
obtain obtained_c, obtained_d from exist x, y R st {x = 2, y = 3}
obtained_c + obtained_d = 5

prop P(a N):
    exist x N st {x = a}
obtain b from $P(-1)

prop P(x set):
    x = x
have by replacement_axiom: Img from prop P, set {1}

have fn f by exist!:
    ? forall x R:
        exist y R st {y = x}

have fn f by exist!:
    ? forall x R:
        exist! y N st {y = -1}

by contra:
    ? 0 $in {0}
    impossible not 0 $in {0}

prop witness_copy(a R):
    exist x R st {x = a}
witness $witness_copy(2) from 2

prop witness_unique(a R):
    exist! x R st {x = a}
witness $witness_unique(3) from 3

prop P(a R):
    exist n N st {n = a}
witness $P(-1) from -1

claim:
    ? exist x R st {x = 9}
